export type json =
  | string
  | number
  | boolean
  | null
  | json[]
  | { [key: string]: json };

export const normalizeProps = (props: json): json =>
  typeof props === "object"
    ? props === null
      ? null
      : Array.isArray(props)
        ? props.map(normalizeProps)
        : Object.fromEntries(
            Object.entries(props).map(([k, v]) => [
              k.replace(/^:+/, ""),
              typeof v === "object" && v !== null && !Array.isArray(v)
                ? normalizeProps(v)
                : Array.isArray(v)
                  ? v.map(normalizeProps)
                  : v,
            ]),
          )
    : props;

export const getRawBlockProps = (uid: string) =>
  (window.roamAlphaAPI.pull("[:block/props]", [":block/uid", uid])?.[
    ":block/props"
  ] || {}) as Record<string, json>;

const getBlockProps = (uid: string) =>
  normalizeProps(getRawBlockProps(uid)) as Record<string, json>;

export default getBlockProps;
import { type json, getRawBlockProps, normalizeProps } from "./getBlockProps";
import getPageUidByPageTitle from "roamjs-components/queries/getPageUidByPageTitle";

export const deNormalizeProps = (props: json): json =>
  typeof props === "object"
    ? props === null
      ? null
      : Array.isArray(props)
        ? props.map(deNormalizeProps)
        : Object.fromEntries(
            Object.entries(props).map(([k, v]) => [
              `:${k}`,
              typeof v === "object" && v !== null && !Array.isArray(v)
                ? deNormalizeProps(v)
                : Array.isArray(v)
                  ? v.map(deNormalizeProps)
                  : v,
            ]),
          )
    : props;

export const setBlockPropsAsync = (
  uid: string,
  newProps: Record<string, json>,
  denormalize: boolean = false,
): Promise<json> => {
  const rawBaseProps = getRawBlockProps(uid);
  const baseProps = denormalize ? rawBaseProps : normalizeProps(rawBaseProps);
  if (typeof baseProps === "object" && !Array.isArray(baseProps)) {
    const props = {
      ...(baseProps || {}),
      ...(denormalize
        ? (deNormalizeProps(newProps) as Record<string, json>)
        : newProps),
    } as Record<string, json>;
    return window.roamAlphaAPI.data.block
      .update({ block: { uid, props } })
      .then(() => props);
  }
  return Promise.resolve(baseProps);
};

const setBlockProps = (
  uid: string,
  newProps: Record<string, json>,
  denormalize: boolean = false,
): void => {
  void setBlockPropsAsync(uid, newProps, denormalize);
};

export const testSetBlockProps = (
  title: string,
  newProps: Record<string, json>,
) => {
  const uid = getPageUidByPageTitle(title);
  return uid ? setBlockPropsAsync(uid, newProps) : null;
};

export default setBlockProps;
